public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    int pos = lb.start;
    byte[] buffer = lb.buffer;

    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            buffer[pos++] = (byte) c;
        } else if (c < 0x800) {
            buffer[pos++] = (byte) (0xC0 | (c >> 6));
            buffer[pos++] = (byte) (0x80 | (c & 0x3F));
        } else if (Character.isHighSurrogate(c)) {
            if (i + 1 < len) {
                char lowSurrogate = str.charAt(++i);
                if (Character.isLowSurrogate(lowSurrogate)) {
                    int codePoint = Character.toCodePoint(c, lowSurrogate);
                    buffer[pos++] = (byte) (0xF0 | (codePoint >> 18));
                    buffer[pos++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                    buffer[pos++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                    buffer[pos++] = (byte) (0x80 | (codePoint & 0x3F));
                } else {
                    // Malformed surrogate pair
                    throw new IllegalArgumentException("Invalid UTF-16 sequence");
                }
            } else {
                // Unpaired high surrogate
                throw new IllegalArgumentException("Invalid UTF-16 sequence");
            }
        } else {
            buffer[pos++] = (byte) (0xE0 | (c >> 12));
            buffer[pos++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            buffer[pos++] = (byte) (0x80 | (c & 0x3F));
        }

        // Check if buffer is full
        if (pos >= lb.offset) {
            LinkedBuffer newLb = lb.next = session.nextBuffer();
            buffer = newLb.buffer;
            pos = newLb.start;
        }
    }

    lb.pos = pos;
    return lb;
}
