// Helper method for variable substitution
private static String substVars(String val, Properties props, Properties sysProps, HashSet<String> cycleProps) {
    StringBuffer sbuf = new StringBuffer();
    int i = 0;
    int j;
    int endIndex;
    while (true) {
        j = val.indexOf("${", i);
        if (j == -1) {
            // no more variables
            if (i == 0) {
                // this is a string with no variable, return origin
                return val;
            } else {
                // add the trailing part which contains no variables and return the whole
                sbuf.append(val.substring(i));
                return sbuf.toString();
            }
        } else {
            sbuf.append(val.substring(i, j));
            endIndex = val.indexOf("}", j);
            if (endIndex == -1) {
                throw new IllegalStateException("No closing brace for property: " + val);
            }
            String key = val.substring(j + 2, endIndex);
            // first try in System properties
            String substValue = sysProps.getProperty(key);
            if (substValue == null) {
                // resrec in regular properties
                substValue = props.getProperty(key);
            }
            if (substValue == null) {
                throw new IllegalStateException("Key '" + key + "' has no value associated");
            }
            if (cycleProps.contains(key)) {
                throw new IllegalStateException("Infinite loop in property interpolation of " + key);
            }
            cycleProps.add(key);
            substValue = substVars(substValue, props, sysProps, cycleProps);
            sbuf.append(substValue);
            i = endIndex + 1;
        }
    }
}
```

