public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return pathSegments;
    }

    // If the path is absolute, ignore the leading '/'
    int start = path.startsWith("/") ? 1 : 0;

    // Split the path by '/' to get segments
    String[] segments = path.substring(start).split("/");

    for (String segment : segments) {
        if (segment.isEmpty()) {
            continue; // Skip empty segments
        }
        String decodedSegment = decode ? decode(segment) : segment;
        pathSegments.add(new PathSegmentImpl(decodedSegment));
    }

    return pathSegments;
}

