public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder writer = new StringBuilder();
    int sz = str.length();
    StringBuilder unicode = new StringBuilder();
    boolean hadSlash = false;
    boolean inUnicode = false;

    for (int i = 0; i < sz; i++) {
        char c = str.charAt(i);
        if (inUnicode) {
            unicode.append(c);
            if (unicode.length() == 4) {
                try {
                    int value = Integer.parseInt(unicode.toString(), 16);
                    writer.append((char) value);
                    unicode.setLength(0);
                    inUnicode = false;
                    hadSlash = false;
                } catch (NumberFormatException nfe) {
                    throw new Exception("Invalid unicode value: " + unicode);
                }
            }
            continue;
        }
        if (c == '\\') {
            if (hadSlash) {
                writer.append(c);
                hadSlash = false;
            } else {
                hadSlash = true;
            }
        } else if (hadSlash) {
            hadSlash = false;
            switch (c) {
                case '\'' :
                    writer.append('\'');
                    break;
                case '"' :
                    writer.append('"');
                    break;
                case '\\' :
                    writer.append('\\');
                    break;
                case 'b' :
                    writer.append('\b');
                    break;
                case 'f' :
                    writer.append('\f');
                    break;
                case 'n' :
                    writer.append('\n');
                    break;
                case 'r' :
                    writer.append('\r');
                    break;
                case 't' :
                    writer.append('\t');
                    break;
                case 'u' :
                    inUnicode = true;
                    break;
                default :
                    throw new Exception("Invalid escape character: " + c);
            }
        } else {
            writer.append(c);
        }
    }
    if (hadSlash) {
        writer.append('\\');
    }

    return writer.toString();
}
