            if (line.trim().isEmpty()) {
                continue;
            }
            String[] parts = line.split(","); // Example delimiter, adjust as necessary
            long timestamp = Long.parseLong(parts[0]); // Assuming the first part is the timestamp
            if (isWithinTimeRanges(timestamp, timeRanges)) {
                ThreadSnapshot snapshot = new ThreadSnapshot(); // Create snapshot object
                // Parse other details and set them in the snapshot object
                // Example: snapshot.setSomeField(parts[i]);
                threadSnapshots.add(snapshot);
            }
        }
    }
    return threadSnapshots;
}

private static boolean isWithinTimeRanges(long timestamp, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
            return true;
        }
    }
    return false;
}
